<?php $q=mysqli_query($koneksi,"SELECT * FROM kategori ORDER BY idkategori DESC"); function fotoKategoriAdmin($nama,$foto){$nama=strtolower((string)$nama);$f=basename((string)$foto);if($f!==''&&is_file(__DIR__.'/../../../assets/uploads/kategori/'.$f))return $f;if(strpos($nama,'elektronik')!==false||strpos($nama,'komputer')!==false)return 'cat_elektronik.jpg';if(strpos($nama,'aksesori')!==false||strpos($nama,'aksesoris')!==false||strpos($nama,'kabel')!==false)return 'cat_aksesoris.jpg';return 'cat_peralatan.jpg';} ?><h2>Kategori Sarana</h2><a class="btn btn-primary mb-3" href="index.php?halaman=createkategori">Tambah</a><table class="table table-bordered"><tr><th>ID</th><th>Gambar</th><th>Kategori</th><th>Aksi</th></tr><?php while($r=mysqli_fetch_assoc($q)): ?><tr><td><?=$r['idkategori']?></td><td><?php $fotoTampil=fotoKategoriAdmin($r['namakategori'],$r['foto']??''); ?><img src="assets/uploads/kategori/<?=htmlspecialchars($fotoTampil,ENT_QUOTES,'UTF-8')?>" alt="Gambar <?=htmlspecialchars($r['namakategori'],ENT_QUOTES,'UTF-8')?>" style="width:75px;height:55px;object-fit:cover;border-radius:6px" loading="lazy"></td><td><?=htmlspecialchars($r['namakategori'])?></td><td><a class="btn btn-sm btn-warning" href="index.php?halaman=editkategori&id=<?=$r['idkategori']?>">Edit</a> <a class="btn btn-sm btn-danger" onclick="return confirm('Hapus?')" href="proses/proseskategori.php?aksi=hapus&id=<?=$r['idkategori']?>">Hapus</a></td></tr><?php endwhile;?></table>